def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    yesterday_bids = []
    rich_alive = 0
    extreme_bidders = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('budget', 0) >= 100:
                rich_alive += 1
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                yesterday_bids.append(float(bid))
                if float(bid) >= 120:
                    extreme_bidders += 1

    if not alive_opponents:
        return float(min(budget, 18.0))

    highest_prev = max(yesterday_bids) if yesterday_bids else 0.0
    avg_prev = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 0.0

    urgency = 0
    if hp <= 2:
        urgency += 4
    elif hp <= 4:
        urgency += 2
    if no_water_days >= 2:
        urgency += 4
    elif no_water_days >= 1:
        urgency += 2

    abundance = (float(supply) - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY)
    if abundance >= 0.8:
        urgency += 1

    if supply <= 16:
        scarcity_level = 2
    elif supply <= 19:
        scarcity_level = 1
    else:
        scarcity_level = 0

    if urgency >= 6:
        bid = 146.0 if budget >= 146.0 else budget
    elif urgency >= 4:
        if scarcity_level == 2:
            bid = 132.0
        elif scarcity_level == 1:
            bid = 118.0
        else:
            bid = 96.0
    else:
        if extreme_bidders >= 2 and scarcity_level >= 1:
            bid = 8.0 if hp > 4 and no_water_days == 0 else 72.0
        elif highest_prev >= 140:
            if scarcity_level == 0:
                bid = 61.0
            else:
                bid = 12.0 if hp > 5 and no_water_days == 0 else 78.0
        elif avg_prev >= 90:
            bid = 68.0 if scarcity_level == 0 else 74.0
        else:
            bid = 52.0 + 10.0 * abundance

    if day >= 8:
        bid += 8.0
    if rich_alive == 0:
        bid *= 0.8

    if hp >= 8 and no_water_days == 0 and scarcity_level == 2 and extreme_bidders >= 1:
        bid = min(bid, 10.0)

    bid = max(0.0, min(float(budget), float(bid)))
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive = []
    for k, o in opponents_status.items():
        if o.get('alive', False):
            alive.append(o)

    if not alive:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Yesterday bids from immediate trace
    yesterday_bids = []
    yesterday_pressured = []
    for o in alive:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                b = float(b)
            except Exception:
                continue
            yesterday_bids.append(b)
            # If they were already low hp / dying, they may bid differently today
            hp_after = prev.get('hp_after', None)
            if hp_after is not None:
                try:
                    hp_after = float(hp_after)
                except Exception:
                    hp_after = None
                if hp_after is not None and hp_after <= 0:
                    yesterday_pressured.append(b)

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Base bid: aim to beat typical competition without matching Cindy's max aggressiveness.
    # If supply is higher, competition is likely lower; bid less.
    supply_norm = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY) if MAX_SUPPLY > MIN_SUPPLY else 0.0
    supply_norm = max(0.0, min(1.0, float(supply_norm)))

    # Determine urgency from hp/no_water_days
    urgency = 0
    if hp <= 2.0:
        urgency += 3
    if hp <= 4.0:
        urgency += 2
    if no_water_days >= 2:
        urgency += 2
    if no_water_days >= 3:
        urgency += 3

    # If the market was very hot yesterday, raise slightly but not to the same level.
    hot_market = highest_prev_bid >= DAILY_SALARY * 0.85

    # Conservative escalation policy
    if urgency >= 5:
        bid = DAILY_SALARY * (0.65 + 0.1 * supply_norm)
    elif urgency >= 3:
        bid = DAILY_SALARY * (0.55 + 0.1 * supply_norm)
    else:
        bid = DAILY_SALARY * (0.42 + 0.08 * supply_norm)

    # If Cindy-like aggressiveness was present (highest_prev_bid high), adjust upward a bit
    # but keep below the top bidder to avoid price lock.
    if hot_market:
        bid = max(bid, min(DAILY_SALARY * 0.6, highest_prev_bid * 0.55 + 5.0))

    # If someone died yesterday, they likely have 0 budget and won't bid much; reduce bid.
    if yesterday_pressured and max(yesterday_pressured) <= DAILY_SALARY * 0.2:
        bid *= 0.9

    # Final cap by budget
    bid = max(0.0, min(budget, bid))

    # Ensure we don't bid trivially when we need water.
    if my_status.get('no_water_days', 0) >= 1 and bid < DAILY_SALARY * 0.25:
        bid = min(budget, DAILY_SALARY * 0.25)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    supply = day_context['supply']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive = len(alive_opponents) + 1

    if num_alive <= 1:
        return 1.0

    fair_share_bid = (DAILY_SALARY * 0.6) if supply / num_alive >= WATER_REQ else (DAILY_SALARY * 0.9)

    yesterday_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]

    if yesterday_bids:
        max_prev = max(yesterday_bids)
        if max_prev > DAILY_SALARY * 1.2:
            return min(my_status['budget'], 1.0) if my_status['hp'] > 3 else min(my_status['budget'], DAILY_SALARY * 0.5)
        return min(my_status['budget'], max(fair_share_bid, max_prev * 1.05))

    return min(my_status['budget'], fair_share_bid)
